export function resolveLanguage(preference = settings.get().language) {
  if (preference === 'en' || preference === 'es') return preference;
  const candidates = typeof navigator === 'undefined' ? [] : [...(navigator.languages || []), navigator.language || ''];
  return candidates.some((language) => /^en(?:-|$)/i.test(language)) ? 'en' : 'es';
}

function interpolate(value, values) {
  return value.replace(/\{(\w+)\}/g, (_, key) => String(values?.[key] ?? `{${key}}`));
}

export function translate(key, values, languageOverride) {
  const language = languageOverride || resolveLanguage();
  let translated = language === 'en' ? messages.en[key] || key : key;
  if (language === 'en' && translated === key) {
    const dynamic = [
      [/^Página (\d+)$/, (_, page) => `Page ${page}`],
      [/^Páginas (\d+)-(\d+)$/, (_, first, last) => `Pages ${first}–${last}`],
      [/^Capítulo (.+)$/, (_, chapter) => `Chapter ${chapter}`],
      [/^Continuando desde la página (\d+)$/, (_, page) => `Continuing from page ${page}`],
      [/^(\d+) capítulos? sin leer$/, (_, count) => `${count} unread ${count === '1' ? 'chapter' : 'chapters'}`],
      [/^Buscar en (.+)\.\.\.$/, (_, name) => `Search ${name}...`],
      [/^Buscar en (.+)…$/, (_, name) => `Search in ${name}…`],
      [/^Buscar mangas en (.+)$/, (_, name) => `Search manga in ${name}`],
      [/^Abrir catálogo de (.+)$/, (_, name) => `Open ${name} catalog`],
      [/^Configuración de (.+)$/, (_, name) => `${name} settings`],
      [/^Actualizar a la v(.+)$/, (_, version) => `Update to v${version}`],
      [/^Actualizar (.+)$/, (_, name) => `Update ${name}`],
      [/^Nombre de la categoría (.+)$/, (_, name) => `Category name: ${name}`],
      [/^Eliminar categoría (.+)$/, (_, name) => `Delete category ${name}`],
      [/^(\d+) mangas en esta categoría$/, (_, count) => `${count} manga in this category`],
      [/^Valoración (\d+) sobre 100$/, (_, score) => `Score ${score} out of 100`]
    ];
    for (const [pattern, format] of dynamic) {
      const match = key.match(pattern);
      if (match) { translated = format(...match); break; }
    }
  }
  return interpolate(translated, values);
}

export function useI18n() {
  const contextLanguage = useContext(LanguageOverrideContext);
  const preference = useSyncExternalStore(
    (onChange) => settings.subscribe(onChange),
    () => settings.get().language,
    () => 'system'
  );
  const language = contextLanguage || resolveLanguage(preference);
  const t = useCallback((key, values) => translate(key, values, language), [language]);
  return { language, t, isLanguagePreview: contextLanguage !== null };
}
